'use strict';
const careState={method:3,conditions:new Set(),selected:new Set()};
const careText=()=>CARE_I18N[language];
function careInherited(p){const out=new Set();if(!p)return out;if(p.history==='0'||p.motion==='0')out.add('nausea');const pairs={2:'heart',3:'breathing',4:'kidney',5:'liver',6:'breathing'};p.diseases.forEach(i=>{if(pairs[i])out.add(pairs[i])});return out;}
function careAssessment(p,state){
 const conditions=new Set([...state.conditions,...careInherited(p)]);
 const related={airway:['airway','breathing'],warming:['cold'],depth:['awareness'],block:['limb'],oxygen:['breathing','airway'],paracetamol:['pain'],dynastat:['pain'],naldebain:['pain'],ondansetron:['nausea']};
 const cautions={airway:[],warming:[],depth:[],block:['bleeding','allergy'],oxygen:[],paracetamol:['liver','kidney','allergy','pregnancy'],dynastat:['liver','kidney','heart','breathing','ulcer','allergy','bleeding','pregnancy'],naldebain:['breathing','liver','kidney','allergy','pregnancy','opioids'],ondansetron:['rhythm','heart','liver','allergy','pregnancy']};
 return CARE_IDS.map(id=>({id,matches:related[id].filter(c=>conditions.has(c)),flags:cautions[id].filter(c=>conditions.has(c)),child:!!p&&Number(p.age)<18,review:['airway','block','oxygen','paracetamol','dynastat','naldebain','ondansetron'].includes(id)}));
}
function careItemInfo(id){return careText().items[CARE_IDS.indexOf(id)]}
function cardForItem(result){const c=careText(),index=CARE_IDS.indexOf(result.id),info=c.items[index],caution=result.flags.length||result.child;const card=document.createElement('article');card.className='care-item'+(caution?' needs-review':'');card.dataset.item=result.id;
 const head=document.createElement('div');head.className='care-item-head';head.append(textElement('span',String(index+1).padStart(2,'0'),'care-item-number'),textElement('h4',info[0]));card.append(head,textElement('span',caution||result.review?c.review:result.matches.length?c.match:c.general,'care-badge'),textElement('p',info[1]));
 if(result.matches.length)card.append(textElement('p',c.reason+result.matches.map(key=>c.conditionLabels[CONDITION_IDS.indexOf(key)]).join(' · '),'care-reason'));
 if(caution)card.append(textElement('p',result.child?c.childReview:c.healthReview,'care-warning'));
 const label=document.createElement('label');label.className='care-choice';const box=document.createElement('input');box.type='checkbox';box.value=result.id;box.checked=careState.selected.has(result.id);box.onchange=()=>{if(box.checked)careState.selected.add(result.id);else careState.selected.delete(result.id);document.querySelectorAll(`input[data-care-id="${result.id}"]`).forEach(other=>other.checked=box.checked);updateCareSummary()};box.dataset.careId=result.id;label.append(box,textElement('span',c.discuss+' · '+info[0]));card.append(label);return card;}
function updateCareSummary(){const el=$('#care-selection-summary');if(el){el.textContent=careText().selectedCount.replace('{n}',careState.selected.size);const list=$('#care-selected-list');list.textContent=careState.selected.size?[...careState.selected].map(id=>careItemInfo(id)[0]).join(' · '):careText().notChosen;}}
function renderCareChoices(){const c=careText(),suggested=$('#care-suggestions'),all=$('#care-all-items');const results=careAssessment(patient,careState);suggested.innerHTML='';all.innerHTML='';const matched=results.filter(r=>r.matches.length);if(!matched.length)suggested.append(textElement('p',c.noMatches,'hint'));matched.forEach(r=>suggested.append(cardForItem(r)));results.forEach(r=>all.append(cardForItem(r)));updateCareSummary();}
function renderPreopCare(root){const c=careText();const section=document.createElement('section');section.className='preop-care';section.innerHTML=`<div class="visitor-banner"><svg viewBox="0 0 100 100" aria-hidden="true">${staffAvatar(50,47,'#93b8a4',false)}</svg><div><h3>${esc(c.visitorTitle)}</h3><p>${esc(c.visitorBody)}</p></div></div><h3>${esc(c.section)}</h3><p>${esc(c.intro)}</p><fieldset class="care-methods"><legend>${esc(c.method)}</legend>${c.methods.map((name,i)=>`<label><input type="radio" name="care-method" value="${i}" ${careState.method===i?'checked':''}>${esc(name)}</label>`).join('')}</fieldset><fieldset class="care-conditions"><legend>${esc(c.conditions)}</legend><div class="condition-grid"></div></fieldset><h3>${esc(c.suggestions)}</h3><div class="care-grid" id="care-suggestions" aria-live="polite"></div><details class="care-all"><summary>${esc(c.allItems)}</summary><div class="care-grid" id="care-all-items"></div></details><div class="care-summary"><h4 id="care-selection-summary"></h4><p id="care-selected-list"></p><p class="hint">${esc(c.costs)}</p><button class="primary" id="save-care">${esc(c.save)}</button><p class="hint">${esc(c.notice)}</p></div>`;
 root.append(section);section.append(careSources());const inherited=careInherited(patient);CONDITION_IDS.forEach((id,i)=>{const label=document.createElement('label'),box=document.createElement('input');box.type='checkbox';box.value=id;box.name='care-condition';box.checked=careState.conditions.has(id)||inherited.has(id);box.disabled=inherited.has(id);box.onchange=()=>{if(box.checked)careState.conditions.add(id);else careState.conditions.delete(id);renderCareChoices()};label.append(box,textElement('span',c.conditionLabels[i]));if(inherited.has(id)){const labels={'zh-Hant':'由基本資料帶入',en:'From your profile',id:'Dari data diri',th:'จากข้อมูลของคุณ',vi:'Từ thông tin cá nhân',fil:'Mula sa iyong impormasyon'};label.append(textElement('small',labels[language]))}section.querySelector('.condition-grid').append(label)});
 section.querySelectorAll('[name=care-method]').forEach(box=>box.onchange=()=>{careState.method=Number(box.value);renderCareChoices()});$('#save-care').onclick=()=>$('#topic-dialog').close();renderCareChoices();
}
function staffAvatar(x,y,color,surgeon){return `<g transform="translate(${x} ${y})"><path d="M-24 48V9Q0-4 24 9V48Z" fill="${color}"/><path d="M-17 48V27m34 21V27" stroke="#385f5d" stroke-width="3"/><circle cy="-9" r="19" fill="#efc7a7"/><path d="M-20-13q0-27 20-23 23-1 20 24Z" fill="${surgeon?'#779f9b':'#b4cec0'}"/><path d="M-18-16H18" stroke="#547c75" stroke-width="2"/><circle cx="-7" cy="-12" r="1.6" fill="#294a45"/><circle cx="7" cy="-12" r="1.6" fill="#294a45"/><path d="M-14-6h28v12q-14 9-28 0Z" fill="#edf7f2" stroke="#98b8ab"/><path d="M-10 0H10M-8 4H8" stroke="#afcfc0"/><path d="M-24 14l-10 24m58-24l10 24" stroke="${color}" stroke-width="12" stroke-linecap="round"/>${surgeon?'':'<path d="M-10 11v13q10 14 20 0V11" fill="none" stroke="#426d68" stroke-width="3"/><circle cx="10" cy="26" r="4" fill="#dfe9e2" stroke="#426d68"/>'}</g>`;}
function medicineIcon(id){const color={paracetamol:'#79a99d',dynastat:'#bc946d',naldebain:'#9b8db6',ondansetron:'#7d9fb8'}[id];return `<svg viewBox="0 0 100 100" aria-hidden="true"><ellipse cx="50" cy="88" rx="28" ry="6" fill="#315c4715"/><rect x="34" y="12" width="32" height="13" rx="3" fill="${color}"/><rect x="30" y="23" width="40" height="61" rx="9" fill="#f6fcf8" stroke="${color}" stroke-width="3"/><path d="M34 56h32v19q0 5-5 5H39q-5 0-5-5Z" fill="${color}" opacity=".24"/><rect x="32" y="38" width="36" height="27" rx="3" fill="${color}"/><path d="M43 51h14m-7-7v14" stroke="#fff" stroke-width="3"/></svg>`;}
function sceneSVG(){const c=careText(),has=id=>careState.selected.has(id);return `<svg id="operating-scene" viewBox="0 0 960 650" role="img" aria-label="${esc(c.sceneTitle)}"><defs><pattern id="room-grid" width="45" height="45" patternUnits="userSpaceOnUse"><path d="M45 0H0V45" fill="none" stroke="#bed2ca" stroke-width=".5"/></pattern></defs><rect width="960" height="650" rx="18" fill="#e6f0e9"/><path d="M0 410H960V650H0Z" fill="#d5e4dc"/><path d="M0 410H960V650H0Z" fill="url(#room-grid)"/><rect x="33" y="25" width="285" height="34" rx="17" fill="#fff9"/><text x="49" y="47" class="room-caption">${esc(c.sceneOnly)}</text>
<!-- Team members remain visible regardless of paid options. -->
<g data-staff="anesthesiologist">${staffAvatar(260,131,'#7fa89b',false)}</g><g data-staff="anesthesia-nurse">${staffAvatar(615,130,'#a6c4ad',false)}</g><g data-staff="surgery-team">${staffAvatar(802,104,'#7aa8a1',true)}${staffAvatar(876,125,'#9ebdb4',true)}</g>
<g class="staff-labels"><rect x="179" y="186" width="162" height="28" rx="14"/><text x="260" y="205">${esc(c.staff[0])}</text><rect x="522" y="183" width="186" height="32" rx="16"/><text x="615" y="204">${esc(c.staff[1])}</text><rect x="747" y="184" width="179" height="28" rx="14"/><text x="837" y="203">${esc(c.staff[2])}</text></g>
<!-- IV pole and bag. -->
<g id="scene-iv"><path d="M119 186V535M95 535h48M119 190h45" stroke="#8ba9a0" stroke-width="7" stroke-linecap="round"/><path d="M155 180v30" stroke="#8ba9a0" stroke-width="3"/><rect x="137" y="207" width="48" height="72" rx="10" fill="#f3fcf8" stroke="#87b4a4" stroke-width="3"/><path d="M141 244h40v24q0 7-7 7H148q-7 0-7-7Z" fill="#b8dfe2"/><path d="M153 231h15m-7-7v14" stroke="#79aaa1" stroke-width="3"/><path d="M161 279v31q0 55 72 45l45-9" fill="none" stroke="#65b9c0" stroke-width="4"/></g>
<!-- Monitor: illustrative waveforms, with no invented patient readings. -->
<g id="scene-monitor"><path d="M774 425V530M739 530h70" stroke="#8ca69d" stroke-width="10"/><rect x="689" y="234" width="205" height="183" rx="15" fill="#557872"/><rect x="703" y="247" width="177" height="156" rx="8" fill="#203f43"/><path class="ecg-wave" d="M713 284h20l7-9 8 20 8-39 9 36 7-8h25l7-9 7 16 9-31 9 24h35" fill="none" stroke="#a2dfaf" stroke-width="3"/><text x="716" y="268" fill="#b5dbbb" font-size="10">ECG</text><path d="M714 328q9-24 18 0t18 0t18 0t18 0t18 0t18 0t18 0t18 0" fill="none" stroke="#a2dfe6" stroke-width="2"/><text x="717" y="316" fill="#b4e4e6" font-size="10">SpO₂　-- %</text><text x="716" y="365" fill="#e6dda9" font-size="12">NIBP　-- / --</text><text x="716" y="387" fill="#c8d4cf" font-size="10">ETCO₂　--</text><circle cx="877" cy="425" r="4" fill="#b1d4b3"/></g>
<!-- Bed and a patient lying flat, viewed from above. -->
<g id="scene-bed"><ellipse cx="449" cy="579" rx="183" ry="28" fill="#2c5c4b16"/><rect x="327" y="210" width="249" height="350" rx="33" fill="#9ab8ac"/><rect x="339" y="216" width="225" height="326" rx="28" fill="#f8fcf5"/><rect x="355" y="225" width="193" height="76" rx="25" fill="#d7e8df"/><path d="M335 337V495M568 337V495" stroke="#a8beb4" stroke-width="9" stroke-linecap="round"/><path d="M368 555v30m165-30v30" stroke="#75968b" stroke-width="10"/><circle cx="368" cy="587" r="10" fill="#51766a"/><circle cx="533" cy="587" r="10" fill="#51766a"/></g>
<g id="scene-patient"><path d="M391 314L315 341L269 346M504 314L558 340L611 349" fill="none" stroke="#efc7a7" stroke-width="26" stroke-linecap="round"/><path d="M388 295q59-24 118 0l9 120H382Z" fill="#f2d1b3"/><rect x="394" y="398" width="107" height="100" rx="19" fill="#b4d0bd"/><path d="M416 472v62m63-62v62" stroke="#efc7a7" stroke-width="25" stroke-linecap="round"/><path d="M405 535h25m37 0h25" stroke="#f8fbf3" stroke-width="14" stroke-linecap="round"/><rect x="422" y="267" width="48" height="30" rx="12" fill="#efc7a7"/><ellipse cx="447" cy="244" rx="46" ry="50" fill="#efc7a7"/><path d="M401 236q-5-67 45-63 51-1 49 65l-17-26q-47 21-72 9Z" fill="#547465"/><path d="M419 244q7 6 14 0m27 0q7 6 14 0" stroke="#6e6f59" stroke-width="2.8" fill="none"/><path d="M438 263q9 5 18 0" stroke="#b48166" stroke-width="2" fill="none"/><path d="M243 345h28m-24 8h20" stroke="#efc7a7" stroke-width="8" stroke-linecap="round"/></g>
<!-- Catheter and oximeter share one arm; cuff is on the other arm. -->
<g id="scene-catheter"><rect x="281" y="334" width="20" height="16" rx="4" fill="#fff9" stroke="#8ab8ae"/><path d="M284 339h15" stroke="#65b9c0" stroke-width="4"/></g><g id="scene-spo2"><rect x="239" y="334" width="21" height="17" rx="5" fill="#76b8bf" stroke="#497b81" stroke-width="2"/><circle cx="248" cy="344" r="3" fill="#f18b75"/><path d="M239 345q-38 8-32 45t130 40l302-42q47-6 50-60" fill="none" stroke="#71aeb6" stroke-width="2.5"/></g>
<g id="scene-bp"><path class="bp-cuff" d="M539 315l30 9-9 34-30-8Z" fill="#7d97bc" stroke="#56739a" stroke-width="2"/><path d="M557 347q46 58 77 34t55-13" fill="none" stroke="#6687af" stroke-width="3"/></g>
<g id="scene-ecg"><path d="M410 309Q572 271 689 278M482 309Q590 285 689 292M481 358Q598 328 689 306" fill="none" stroke="#778f7a" stroke-width="2"/><circle cx="410" cy="309" r="11" fill="#fff" stroke="#a3b6a8" stroke-width="3"/><circle cx="482" cy="309" r="11" fill="#3e554c" stroke="#d2dfd3" stroke-width="3"/><circle cx="481" cy="358" r="11" fill="#d89585" stroke="#e4c8ba" stroke-width="3"/></g>
<!-- A normal sheet is present even without a self-pay warming option. -->
<path d="M385 389h128v129q-63 21-128 0Z" fill="#a9cdb7" stroke="#8bb39a" stroke-width="2"/>
${has('warming')?'<g id="scene-warming" data-option="warming"><path d="M378 382h143v143q-73 22-143 0Z" fill="#efbc78" stroke="#cf9c60" stroke-width="3"/><path d="M386 401h126m-126 21h126m-126 21h126m-126 21h126m-126 21h126m-126 21h126" stroke="#f9d69b" stroke-width="7"/><path d="M517 470q60-10 64 32" fill="none" stroke="#dba76f" stroke-width="14"/><rect x="565" y="499" width="53" height="49" rx="8" fill="#f4e6cf" stroke="#be9a71"/><circle cx="591" cy="519" r="10" fill="#c9ac7c"/></g>':''}
${has('depth')?'<g id="scene-depth" data-option="depth"><path d="M412 222q35-12 70 0" fill="none" stroke="#efeee0" stroke-width="13"/><circle cx="421" cy="220" r="4" fill="#8c99b9"/><circle cx="445" cy="217" r="4" fill="#8c99b9"/><circle cx="471" cy="220" r="4" fill="#8c99b9"/><path d="M482 222q33-69 81-20" fill="none" stroke="#929fbb" stroke-width="3"/><rect x="548" y="206" width="77" height="49" rx="7" fill="#8f9fb2"/><rect x="556" y="213" width="61" height="32" rx="4" fill="#2d4755"/><text x="587" y="235" fill="#c9d5e7" font-size="13" text-anchor="middle">EEG --</text></g>':''}
${has('oxygen')?'<g id="scene-oxygen" data-option="oxygen"><path d="M420 251q26 10 54 0" fill="none" stroke="#a5d4e0" stroke-width="5"/><path d="M421 251Q360 238 340 414Q329 470 250 493" fill="none" stroke="#93c9d7" stroke-width="8"/><rect x="191" y="469" width="66" height="69" rx="10" fill="#e6f6f4" stroke="#7caeb7" stroke-width="3"/><rect x="201" y="480" width="45" height="24" rx="4" fill="#92b8be"/><text x="224" y="497" font-size="10" fill="#fff" text-anchor="middle">HF O₂</text></g>':'<g id="scene-air-mask"><ellipse cx="447" cy="258" rx="22" ry="15" fill="#d1e4de" fill-opacity=".55" stroke="#8aaba2" stroke-width="2"/><path d="M465 262q65 8 91 32" fill="none" stroke="#a8c8bd" stroke-width="5"/></g>'}
${has('airway')?'<g id="scene-airway" data-option="airway"><rect x="54" y="380" width="92" height="56" rx="9" fill="#faf9ed" stroke="#9db6a6" stroke-width="3"/><path d="M72 418v-24h35q14 0 14 12" fill="none" stroke="#88afa2" stroke-width="5"/><circle cx="129" cy="421" r="5" fill="#b6d3b8"/></g>':''}
${has('block')?'<g id="scene-block" data-option="block"><circle cx="526" cy="361" r="23" fill="#d5d8ec" fill-opacity=".7" stroke="#a6a3c3" stroke-dasharray="4 4"/><path d="M518 360l16-8m-9 18l9-18-20-4" fill="none" stroke="#8d8aac" stroke-width="2"/></g>':''}
<!-- Numbered callouts link to plain-language explanations under the drawing. -->
<g class="room-callouts"><path d="M115 300L152 259M595 381L554 338M615 273L482 309M195 390L249 343"/><circle cx="115" cy="300" r="15"/><text x="115" y="305">1</text><circle cx="595" cy="381" r="15"/><text x="595" y="386">2</text><circle cx="615" cy="273" r="15"/><text x="615" y="278">3</text><circle cx="195" cy="390" r="15"/><text x="195" y="395">4</text></g><g><rect x="638" y="433" width="285" height="49" rx="10" fill="#fff9"/><text x="654" y="456" class="bp-label">${esc(c.bp)}</text><text x="654" y="473" font-size="10" fill="#6c8275">NIBP</text></g><text x="447" y="617" text-anchor="middle" class="room-patient-name">${esc(patient.name)}</text></svg>`;}
function renderOperatingRoom(root){const c=careText();root.innerHTML=`<div class="station-chip">${esc(t('station',{n:3}))}</div><h2 id="topic-title">${esc(c.sceneTitle)}</h2><p class="hint">${esc(c.sceneIntro)}</p><div class="room-layout"><div class="room-illustration">${sceneSVG()}<p class="hint">${esc(c.bpNote)}</p></div><aside class="room-legend"><h3>${esc(c.basic)}</h3><ol>${[c.labels[0],c.labels[1],c.labels[2],c.labels[3]].map((label,i)=>`<li><b>${i+1}</b><span>${esc(label)}${i===1?`<small>${esc(c.bp)}</small>`:''}${i===2?`<small>${esc(c.leadHint)}</small>`:''}</span></li>`).join('')}</ol><p class="hint">${esc(c.basicNote)}</p><p class="hint">${esc(c.method)}: ${esc(c.methods[careState.method])}</p><h3>${esc(c.optional)}</h3><div class="selected-scene-list">${careState.selected.size?[...careState.selected].map(id=>`<span data-scene-item="${id}">✓ ${esc(careItemInfo(id)[0])}</span>`).join(''):`<p class="hint">${esc(c.notChosen)}</p>`}</div><button id="scene-edit" class="secondary">${esc(c.edit)}</button><section class="medicine-section"><h3>${esc(c.medTitle)}</h3><div class="medicine-grid"></div><p class="hint">${esc(c.medNote)}</p></section></aside></div><button class="primary" id="scene-back">${esc(t('backMap'))}</button>`;
 const meds=['paracetamol','dynastat','naldebain','ondansetron'].filter(id=>careState.selected.has(id));if(!meds.length)root.querySelector('.medicine-section').hidden=true;meds.forEach(id=>{const card=document.createElement('article');card.className='medicine-card';card.dataset.medicine=id;card.innerHTML=medicineIcon(id);card.append(textElement('strong',careItemInfo(id)[0]));card.title=careItemInfo(id)[1];root.querySelector('.medicine-grid').append(card)});root.append(careSources());$('#scene-back').onclick=()=>$('#topic-dialog').close();$('#scene-edit').onclick=()=>{$('#topic-dialog').close();visit(0)};
}

function careSources(){const details=document.createElement('details');details.className='care-sources';details.append(textElement('summary',careText().sources));const sources=[['ASA · Monitoring','https://www.asahq.org/standards-and-practice-parameters/standards-for-basic-anesthetic-monitoring'],['Paracetamol / Acetaminophen · DailyMed','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=464e404a-1957-44a2-a53a-f2a9d3c15bde'],['Dynastat · Medsafe','https://www.medsafe.govt.nz/profs/datasheet/d/Dynastatinj.pdf'],['Naldebain · Product information','https://www.tai-an.com.tw/upload/DrugInfo/Drug/Instructions/INAB.pdf'],['Ondansetron · MedlinePlus','https://medlineplus.gov/druginfo/meds/a606022.html']];sources.forEach(([name,url])=>{const a=textElement('a',name+' ↗');a.href=url;a.target='_blank';a.rel='noopener';details.append(a)});return details;}
